export interface ConnectFieldSchema {
  key: string;
  label: string;
  type: 'text' | 'password' | 'number' | 'select';
  required?: boolean;
  defaultValue?: string | number;
  placeholder?: string;
  options?: string[];
}

export interface MsmeConnectSchema {
  provider: string;
  connectionType: 'api' | 'import';
  title: string;
  helpText: string;
  fields: ConnectFieldSchema[];
}

export const MSME_CONNECTOR_CONNECT_SCHEMAS: Record<string, MsmeConnectSchema> = {
  tally: {
    provider: 'tally',
    connectionType: 'import',
    title: 'TallyPrime (file import)',
    helpText:
      'Live Connect is unavailable remotely — TallyPrime HTTP API only works on localhost. Export Day Book from TallyPrime and use Import file on the connector card.',
    fields: [],
  },
  zoho: {
    provider: 'zoho',
    connectionType: 'api',
    title: 'Connect Zoho Books',
    helpText:
      'Create a Zoho API client (India data center), generate a refresh token with Zoho Books scope, and paste credentials below.',
    fields: [
      { key: 'organizationId', label: 'Organization ID', type: 'text', required: true },
      { key: 'clientId', label: 'Client ID', type: 'text', required: true },
      { key: 'clientSecret', label: 'Client secret', type: 'password', required: true },
      { key: 'refreshToken', label: 'Refresh token', type: 'password', required: true },
      {
        key: 'apiDomain',
        label: 'API domain',
        type: 'text',
        defaultValue: 'https://www.zohoapis.in',
      },
      {
        key: 'accountsDomain',
        label: 'Accounts domain',
        type: 'text',
        defaultValue: 'https://accounts.zoho.in',
      },
    ],
  },
  quickbooks: {
    provider: 'quickbooks',
    connectionType: 'api',
    title: 'Connect QuickBooks Online',
    helpText:
      'Use your Intuit developer app credentials and OAuth refresh token for your India company realm.',
    fields: [
      { key: 'realmId', label: 'Realm ID (company)', type: 'text', required: true },
      { key: 'clientId', label: 'Client ID', type: 'text', required: true },
      { key: 'clientSecret', label: 'Client secret', type: 'password', required: true },
      { key: 'refreshToken', label: 'Refresh token', type: 'password', required: true },
      {
        key: 'environment',
        label: 'Environment',
        type: 'select',
        options: ['production', 'sandbox'],
        defaultValue: 'production',
      },
    ],
  },
};

export const getMsmeConnectSchema = (providerId: string): MsmeConnectSchema => {
  const normalized = providerId.trim().toLowerCase();
  if (MSME_CONNECTOR_CONNECT_SCHEMAS[normalized]) {
    return MSME_CONNECTOR_CONNECT_SCHEMAS[normalized];
  }
  return {
    provider: normalized,
    connectionType: 'import',
    title: `Use ${normalized}`,
    helpText:
      'Mark this tool as your accounting source. Import JSON or CSV exports using the Import file button on this card.',
    fields: [],
  };
};
