import React, { useEffect, useState } from 'react';
import {
  Alert,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  TextField,
  Typography,
} from '@mui/material';

export interface UncertaintyClarificationField {
  id: string;
  metadataField: string;
  label: string;
  kind?: 'choice' | 'number' | 'text';
  required?: boolean;
  options?: Array<{ value: string; label: string }>;
}

export interface UncertaintyClarificationQuestion {
  transactionId: string;
  description?: string;
  amount?: number;
  promptId?: string | null;
  title?: string;
  question?: string;
  helper?: string;
  example?: string;
  agentMessage?: string;
  quantityLabel?: string;
  quantity?: string;
  unit?: string;
  unitOptions?: string[];
  fields?: UncertaintyClarificationField[];
  extraFields?: Array<{ id: string; label: string; metadataField: string }>;
  requireAirports?: boolean;
  requireMaterialName?: boolean;
  inputKind?: 'activity' | 'unit_price';
  factorId?: string;
  activityUnit?: string;
  unitPriceLabel?: string;
}

export interface IdentifiedSpendPrice {
  transactionId: string;
  description?: string;
  amount?: number;
  priceInr: number;
  priceLabel: string;
  factorId: string;
  citation?: string;
  co2Emissions?: number | null;
  formula?: string;
}

interface AnswerDraft {
  text: string;
  quantity: string;
  unit: string;
  originAirport: string;
  destinationAirport: string;
  materialName: string;
  answers: Record<string, string>;
}

const emptyDraft = (question: UncertaintyClarificationQuestion): AnswerDraft => ({
  text: '',
  quantity: question.quantity || '',
  unit: question.unit || question.unitOptions?.[0] || '',
  originAirport: '',
  destinationAirport: '',
  materialName: '',
  answers: {},
});

const answerNote = (question: UncertaintyClarificationQuestion, draft: AnswerDraft) => {
  const written = draft.text.trim();
  if (written.length >= 3) return written;
  const parts = (question.fields || []).flatMap((field) => {
    const value = String(draft.answers[field.metadataField] || '').trim();
    if (!value) return [];
    if (field.kind === 'choice') {
      return [field.options?.find((option) => option.value === value)?.label || value];
    }
    if (field.kind === 'number') return [`${value} ${field.label}`];
    return [value];
  });
  (question.extraFields || []).forEach((field) => {
    const value = String(draft.answers[field.metadataField] || '').trim();
    if (value) parts.push(`${value} ${field.label}`);
  });
  if (question.inputKind === 'unit_price' && Number(draft.answers.unitPriceInr) > 0) {
    parts.push(`${draft.answers.unitPriceInr} ${question.unitPriceLabel || 'per unit'}`);
  }
  if (draft.materialName.trim()) parts.push(draft.materialName.trim());
  if (parts.length > 0) return parts.join(', ');
  if (Number(draft.quantity) > 0 && draft.unit.trim()) {
    return `${Number(draft.quantity)} ${draft.unit.trim()}`;
  }
  return '';
};

export const buildUncertaintyAnswer = (
  question: UncertaintyClarificationQuestion,
  draft: AnswerDraft
) => {
  const note = answerNote(question, draft);
  if (question.inputKind === 'unit_price') {
    const price = Number(draft.answers.unitPriceInr);
    return {
      carbonInputBasis: 'spend' as const,
      unitPriceInr: price,
      transactionClarification: note || `${price} ${question.unitPriceLabel || 'per unit'}`,
      clarificationWithoutBill: true,
    };
  }
  return {
    carbonInputBasis: 'activity' as const,
    quantity: Number(draft.quantity),
    unit: draft.unit.trim(),
    transactionClarification: note,
    clarificationWithoutBill: true,
    materialName: draft.materialName.trim() || undefined,
    originAirport: draft.originAirport.trim() || undefined,
    destinationAirport: draft.destinationAirport.trim() || undefined,
    ...Object.fromEntries(
      Object.entries(draft.answers).filter(([, value]) => String(value || '').trim())
    ),
  };
};

interface UncertaintyClarificationAgentDialogProps {
  open: boolean;
  loading: boolean;
  saving: boolean;
  error: string | null;
  questions: UncertaintyClarificationQuestion[];
  identifiedPrices?: IdentifiedSpendPrice[];
  onClose: () => void;
  onSubmit: (question: UncertaintyClarificationQuestion, body: ReturnType<typeof buildUncertaintyAnswer>) => void;
}

const UncertaintyClarificationAgentDialog: React.FC<UncertaintyClarificationAgentDialogProps> = ({
  open,
  loading,
  saving,
  error,
  questions,
  identifiedPrices = [],
  onClose,
  onSubmit,
}) => {
  const question = questions[0];
  const [draft, setDraft] = useState<AnswerDraft | null>(null);
  const [localError, setLocalError] = useState<string | null>(null);

  useEffect(() => {
    setDraft(question ? emptyDraft(question) : null);
    setLocalError(null);
  }, [question?.transactionId]);

  const submit = () => {
    if (!question || !draft) return;
    const missingField = (question.fields || []).find((field) => {
      const value = String(draft.answers[field.metadataField] || '').trim();
      if (!field.required) return false;
      return field.kind === 'number' ? !(Number(value) > 0) : !value;
    });
    if (missingField) {
      setLocalError(`Enter ${missingField.label}.`);
      return;
    }
    if (draft.answers.fertilizerType === 'other' && !String(draft.answers.fertilizerProductName || '').trim()) {
      setLocalError('Name the fertilizer product when the type is Other.');
      return;
    }
    if (question.inputKind === 'unit_price') {
      if (!(Number(draft.answers.unitPriceInr) > 0)) {
        setLocalError(`Enter the ${question.unitPriceLabel || 'unit price'}.`);
        return;
      }
    } else {
      const extrasFilled = (question.extraFields || []).length > 0
        && (question.extraFields || []).every((field) => Number(draft.answers[field.metadataField]) > 0);
      if (!extrasFilled && (!(Number(draft.quantity) > 0) || !draft.unit.trim())) {
        setLocalError('Enter a quantity and unit.');
        return;
      }
    }
    if (question.requireAirports && (!draft.originAirport.trim() || !draft.destinationAirport.trim())) {
      setLocalError('Enter the origin and destination airports.');
      return;
    }
    if (question.requireMaterialName && !draft.materialName.trim() && answerNote(question, draft).length < 3) {
      setLocalError('Name the material or activity.');
      return;
    }
    const note = answerNote(question, draft);
    if (note.length < 3) {
      setLocalError('Answer the agent before this row can be calculated.');
      return;
    }
    setLocalError(null);
    onSubmit(question, buildUncertaintyAnswer(question, draft));
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth aria-labelledby="uncertainty-agent-title">
      <DialogTitle id="uncertainty-agent-title">Carbon clarification agent</DialogTitle>
      <DialogContent>
        <Stack spacing={1.5} sx={{ mt: 1 }}>
          {loading ? (
            <Typography variant="body2">The agent is reviewing quantities and units.</Typography>
          ) : null}
          {!loading && identifiedPrices.length > 0 ? (
            <Alert severity="success">
              {identifiedPrices.map((row) => (
                `${row.description || 'This voucher'} uses ${row.priceLabel} ${row.priceInr}. Carbon uses (spend amount ÷ unit price) × the emission factor${row.co2Emissions != null ? ` (${Number(row.co2Emissions).toFixed(2)} kg CO2e)` : ''}.`
              )).join(' ')}
            </Alert>
          ) : null}
          {!loading && !question && identifiedPrices.length === 0 ? (
            <Alert severity="success">No uncertain quantities need an answer.</Alert>
          ) : null}
          {question && draft ? (
            <>
              <Typography variant="caption" color="text.secondary">
                {`Question 1 of ${questions.length}`}
              </Typography>
              <Alert severity="info">{question.agentMessage || question.question}</Alert>
              {question.helper ? (
                <Typography variant="body2" color="text.secondary">{question.helper}</Typography>
              ) : null}
              {question.example ? (
                <Typography variant="body2" color="text.secondary">{`Example: ${question.example}`}</Typography>
              ) : null}
              {(question.fields || []).map((field) => (
                field.kind === 'choice' ? (
                  <FormControl key={field.id} fullWidth size="small">
                    <InputLabel id={`${field.id}-label`}>{field.label}</InputLabel>
                    <Select
                      labelId={`${field.id}-label`}
                      label={field.label}
                      value={draft.answers[field.metadataField] || ''}
                      onChange={(event) => setDraft({
                        ...draft,
                        answers: { ...draft.answers, [field.metadataField]: String(event.target.value) },
                      })}
                    >
                      <MenuItem value="" disabled>Select</MenuItem>
                      {(field.options || []).map((option) => (
                        <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                ) : (
                  <TextField
                    key={field.id}
                    size="small"
                    label={field.label}
                    type={field.kind === 'number' ? 'number' : 'text'}
                    value={draft.answers[field.metadataField] || ''}
                    onChange={(event) => setDraft({
                      ...draft,
                      answers: { ...draft.answers, [field.metadataField]: event.target.value },
                    })}
                    fullWidth
                  />
                )
              ))}
              {(question.fields || []).length === 0
                && question.inputKind !== 'unit_price'
                && question.promptId !== 'activity_quantity_missing'
                && question.promptId !== 'service_count_missing' ? (
                <TextField
                  size="small"
                  label={question.question || 'What is this transaction?'}
                  value={draft.text}
                  onChange={(event) => setDraft({ ...draft, text: event.target.value })}
                  placeholder={question.example || ''}
                  fullWidth
                  multiline
                  minRows={2}
                />
              ) : null}
              {question.requireMaterialName ? (
                <TextField
                  size="small"
                  label="Material or activity name"
                  value={draft.materialName}
                  onChange={(event) => setDraft({ ...draft, materialName: event.target.value })}
                  fullWidth
                />
              ) : null}
              {question.requireAirports ? (
                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
                  <TextField
                    size="small"
                    label="Origin airport"
                    value={draft.originAirport}
                    onChange={(event) => setDraft({ ...draft, originAirport: event.target.value.toUpperCase() })}
                    fullWidth
                  />
                  <TextField
                    size="small"
                    label="Destination airport"
                    value={draft.destinationAirport}
                    onChange={(event) => setDraft({ ...draft, destinationAirport: event.target.value.toUpperCase() })}
                    fullWidth
                  />
                </Stack>
              ) : null}
              {question.inputKind === 'unit_price' ? (
                <TextField
                  size="small"
                  label={question.unitPriceLabel || 'Unit price (₹)'}
                  type="number"
                  value={draft.answers.unitPriceInr || ''}
                  onChange={(event) => setDraft({
                    ...draft,
                    answers: { ...draft.answers, unitPriceInr: event.target.value },
                  })}
                  fullWidth
                />
              ) : null}
              {question.inputKind !== 'unit_price' ? (question.extraFields || []).map((field) => (
                <TextField
                  key={field.id}
                  size="small"
                  label={field.label}
                  type="number"
                  value={draft.answers[field.metadataField] || ''}
                  onChange={(event) => setDraft({
                    ...draft,
                    answers: { ...draft.answers, [field.metadataField]: event.target.value },
                  })}
                  fullWidth
                />
              )) : null}
              {question.inputKind !== 'unit_price' ? (
              <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
                <TextField
                  size="small"
                  label={question.quantityLabel || 'Quantity'}
                  type="number"
                  value={draft.quantity}
                  onChange={(event) => setDraft({ ...draft, quantity: event.target.value })}
                  fullWidth
                />
                {(question.unitOptions || []).length > 0 ? (
                  <FormControl fullWidth size="small">
                    <InputLabel id="uncertainty-unit-label">Unit</InputLabel>
                    <Select
                      labelId="uncertainty-unit-label"
                      label="Unit"
                      value={draft.unit}
                      onChange={(event) => setDraft({ ...draft, unit: String(event.target.value) })}
                    >
                      {(question.unitOptions || []).map((unit) => (
                        <MenuItem key={unit} value={unit}>{unit}</MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                ) : (
                  <TextField
                    size="small"
                    label="Unit"
                    value={draft.unit}
                    onChange={(event) => setDraft({ ...draft, unit: event.target.value })}
                    fullWidth
                  />
                )}
              </Stack>
              ) : null}
            </>
          ) : null}
          {(localError || error) ? <Alert severity="error">{localError || error}</Alert> : null}
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={saving}>Close</Button>
        {question ? (
          <Button variant="contained" onClick={submit} disabled={saving || loading}>
            {saving ? 'Saving…' : 'Save answer'}
          </Button>
        ) : null}
      </DialogActions>
    </Dialog>
  );
};

export default UncertaintyClarificationAgentDialog;
